draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // dog body
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // dog head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // ears
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 - 70);
  ctx.lineTo(W/2 - 30, H/2 - 90);
  ctx.lineTo(W/2 - 15, H/2 - 110);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 15, H/2 - 70);
  ctx.lineTo(W/2 + 30, H/2 - 90);
  ctx.lineTo(W/2 + 15, H/2 - 110);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 + 20);
  ctx.lineTo(W/2 - 20, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 10, H/2 + 20);
  ctx.lineTo(W/2 + 20, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 10, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // mournful pose
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2, H/2 - 30 + 20 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
